"use client";
import { useState } from "react";
export default function Ecommerce() {
  const [cart, setCart] = useState(0);
  const products = [{ id: 1, name: "AI Provider OS Pro", price: 29 }, { id: 2, name: "200 Providers Pack", price: 49 }];
  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white p-8">
      <header className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Loja AI</h1>
        <div className="px-4 py-2 rounded-lg bg-[#11111b] border border-[#1e1e2e]">Carrinho: {cart}</div>
      </header>
      <div className="grid grid-cols-2 gap-6 mt-8">
        {products.map(p => (
          <div key={p.id} className="p-6 rounded-xl bg-[#11111b] border border-[#1e1e2e]">
            <div className="font-bold">{p.name}</div>
            <div className="text-slate-400 mt-2">${p.price}</div>
            <button onClick={() => setCart(c => c + 1)} className="mt-4 px-4 py-2 rounded-lg bg-white text-black">Adicionar</button>
          </div>
        ))}
      </div>
    </div>
  );
}

